{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Increase the fixed norm of tied item embeddings from 1.0 to 1.1 across all four datasets. Slightly larger representations may improve GRU input sensitivity and score separation. Preserve zero padding, dimensions, GRU topology, readout, scoring, loss and optimizer; synchronize checkpoint metadata and predictor validation.",
      "edits": [
        {
          "find": "        embeddings = torch.nn.functional.normalize(embeddings, p=2, dim=-1, eps=1e-12)\n",
          "replace": "        embeddings = 1.1 * torch.nn.functional.normalize(embeddings, p=2, dim=-1, eps=1e-12)\n"
        },
        {
          "find": "            \"dropout_rate\": DROPOUT_RATE,\n            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_3\",\n",
          "replace": "            \"dropout_rate\": DROPOUT_RATE,\n            \"item_embedding_norm\": 1.1,\n            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_3\",\n"
        },
        {
          "find": "        if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_3\":\n            raise RuntimeError(f\"Incompatible GRU sequence readout for {ds}\")\n",
          "replace": "        if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_3\":\n            raise RuntimeError(f\"Incompatible GRU sequence readout for {ds}\")\n        if meta.get(\"item_embedding_norm\") != 1.1:\n            raise RuntimeError(f\"Incompatible GRU item embedding norm for {ds}\")\n"
        }
      ]
    }
  ],
  "change_summary": "Scale tied nonpadding item embeddings to norm 1.1 and synchronize metadata with the embedded predictor, which imports the updated model. Retain one GRU4Rec checkpoint per category and all existing training settings."
